pub use semio_framework_value_native_owned::*;
use semio_framework_value_ordered::OrderedSet;
use semio_framework_value_testing_allocator::observe_retirement_allocations as heap;
use semio_framework_value_testing_admission as source_fixture;
use source_fixture::{Wallet,receive,post_step_with_work,denials,close_owned};
const BODY:usize=32768;
#[test]fn original_set_receiving_matches_fixture_admits_every_insert_and_closes_every_partial_owner(){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📐️.json")).unwrap();assert_eq!(law["publicationFields"],serde_json::json!(["mapOption","setOption"]));for case in law["cases"].as_array().unwrap(){for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100000)){let mut bank=Wallet::from_profile(&law["stock"]);let s=source_fixture::capture(DslValue::Array(case["members"].as_array().unwrap().iter().map(|m|DslValue::String(m.as_str().unwrap().into())).collect()),&mut bank,|w|w.loan(1,BODY),|w,p,work,h,g|w.post(p,work,g,h));let foreign=source_fixture::capture(DslValue::Array(case["members"].as_array().unwrap().iter().map(|m|DslValue::String(m.as_str().unwrap().into())).collect()),&mut bank,|w|w.loan(1,BODY),|w,p,work,h,g|w.post(p,work,g,h));let(mut r,h)=heap(<OrderedSet as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut c=NativeDecodeControl::new(1<<26,&mut callback);for turn in 0..cut{if r.output_ready(){break}let units=bank.remaining_work();let d=r.demands(s.borrow(),BODY,units).unwrap();assert!(d.copy_bytes<=BODY,"original set header exceeds native policy: {d:?}");let g=bank.loan(1,BODY);for denied in denials(g,d){let(t,h)=heap(||receive(&mut c,denied,bank.work_loan(units),|c|r.advance(s.borrow(),c,BODY,units,denied)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(s.borrow(),BODY,units).unwrap(),d)}let(t,h)=heap(||receive(&mut c,g,bank.work_loan(units),|c|r.advance(s.borrow(),c,BODY,units,g)));assert!(t.result.as_ref().unwrap().progress().fits(g),"actual set receipt exceeds {g:?} on turn {turn}");post_step_with_work(&mut bank,t,g,units,h,OriginalReceivingPrimary::retained_progress).unwrap();if !r.output_ready(){assert!(r.demands(foreign.borrow(),BODY,bank.remaining_work()).is_err(),"set accepted a foreign source after its original binding")}}if r.output_ready(){let g=bank.loan(1,BODY);let units=r.take_work_demand().unwrap();let mut output=None;let((poll,actual),h)=heap(||source_fixture::with_effect(&bank,g,units,|effect|r.take(&mut output,effect)));let t=match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("funded original set publication stayed pending")};let p=t.result.unwrap().progress();if let Some(bytes)=actual{assert_eq!(bytes,p.retained_capacity_bytes)}assert_eq!(p.copied_bytes,std::mem::size_of::<Option<semio_framework_value_ordered::OrderedMap<()>>>()+std::mem::size_of::<Option<OrderedSet>>());bank.post(p,t.work,g,h);let set=output.take().expect("actual original set output absent");let members:Vec<_>=set.iter().map(|m|serde_json::json!(m)).collect();assert_eq!(serde_json::Value::Array(members),case["expected"]);let oracle:std::collections::BTreeSet<&str>=case["members"].as_array().unwrap().iter().map(|m|m.as_str().unwrap()).collect();assert!(set.iter().map(String::as_str).eq(oracle.into_iter()));close_owned(set,&mut bank,BODY,100000)}else{assert_ne!(cut,100000,"actual set preparation stalled")}r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){break}let d=r.close_demands(BODY).unwrap();let g=bank.loan(1,BODY);let units=r.close_work_demand(BODY).unwrap();for denied in denials(g,d){let mut actual=None;let(t,h)=heap(||r.close_step(&mut RetainedAllocationEffect::new(denied,units,&mut actual)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(actual,None);assert_eq!(h,(0,0));assert_eq!(r.close_demands(BODY).unwrap(),d)}let mut actual=None;let(t,h)=heap(||r.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual)));let progress=t.result.as_ref().map(|step|step.progress()).unwrap_or_else(|failure|failure.retained_progress());if let Some(bytes)=actual{assert_eq!(bytes,progress.retained_capacity_bytes)}post_step_with_work(&mut bank,t,g,units,h,|failure|failure.retained_progress()).unwrap();}assert!(r.terminal_is_empty());close_owned(s,&mut bank,BODY,100000);close_owned(foreign,&mut bank,BODY,100000);}}}
